<script setup lang="ts">
import {bangkok,type Reservation,type Page} from '~/utils/types'
const api=useApi();const {courier}=useSession();const reservations=ref<Reservation[]>([]);const loading=ref(false);const saving=ref(false);const error=ref<unknown>();const message=ref('');const selected=ref<Reservation|null>(null);const reason=ref('')
async function load(){if(!courier.value)return;loading.value=true;error.value=undefined;try{reservations.value=(await api.get<Page<Reservation>>('/courier/reservations')).items}catch(e){error.value=e}finally{loading.value=false}}
async function cancel(){if(!selected.value)return;saving.value=true;error.value=undefined;try{await api.command(`/courier/reservations/${selected.value.id}?expected_version=${selected.value.version}`,{reason:reason.value.trim()},'DELETE');selected.value=null;reason.value='';message.value='ยกเลิกการจองแล้ว';await load()}catch(e){error.value=e}finally{saving.value=false}}
onMounted(load)
</script>
<template><div class="page-head"><div><h1>การจองของฉัน</h1><p>การจองยังไม่เปลี่ยนผู้ถือครองหนังสือ เวลาหมดอายุอ้างอิงจากเซิร์ฟเวอร์</p></div><button class="button" :disabled="loading" @click="load">โหลดล่าสุด</button></div><Feedback v-if="!courier" :error="new Error('บัญชีนี้ไม่มีสิทธิ์ Courier')" /><template v-else><Feedback :error="error" :message="message" /><section class="panel"><UProgress v-if="loading" /><div v-if="!reservations.length&&!loading" class="empty"><h2>ไม่มีการจองที่ใช้งานอยู่</h2><NuxtLink class="text-link" to="/worklist">เลือกหนังสือจากงานประจำ Station</NuxtLink></div><article v-for="r in reservations" :key="r.id" class="timeline"><div class="actions"><StatusTag :value="r.status" /><p>หมดอายุ {{bangkok(r.expires_at)}}</p></div><div v-for="item in r.items" :key="item.document_id"><p class="break">หนังสืออ้างอิง {{item.document_id}}</p></div><button v-if="r.status==='ACTIVE'" type="button" class="button actions" @click="selected=r;reason=''">ยกเลิกการจอง</button></article></section><form v-if="selected" class="panel" @submit.prevent="cancel"><h2>ยกเลิกการจอง</h2><div class="field"><label for="cancel-reason">เหตุผล</label><textarea id="cancel-reason" v-model="reason" required maxlength="1000" /></div><div class="actions"><button class="button danger" :disabled="saving">{{saving?'กำลังยกเลิก…':'ยืนยันยกเลิกการจอง'}}</button><button class="button" type="button" @click="selected=null">กลับ</button></div></form></template></template>
